fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    let mut iter = strings.into_iter();
    // If the input list is empty, return None.
    let mut best = match iter.next() {
        None => return None,
        Some(first) => first,
    };
    let mut max_len = best.len();

    // Iterate over the rest, updating only when we find a strictly longer sequence.
    for s in iter {
        let len = s.len();
        if len > max_len {
            max_len = len;
            best = s;
        }
    }

    Some(best)
}

